head.script:
scwin.gVar = {
    "cTabIndexTarget" : "",
    "cTabIndexInput" : "",
    "cTabIndexButton" : "",
    "cTabIndexSelectBox" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > tabIndex]<br/>Tab 키를 사용하여 컴포넌트 간 포커스를 이동할때 MultiSelect 컴포넌트의 순서를 설정합니다.",
    "validation" : [
        "Tab 키에 의한 포커스 이동 순서를 양수, 0, 음수로 설정할 수 있어야 합니다.",
        "0(default) 으로 설정 시 Tab 키에 의한 기본 포커스 이동 순서에 포함되어야 합니다.",
        "양의 정수로 설정 시 해당 순서로 포커스 이동에 포함되어야 합니다.",
        "음의 정수로 설정 시 Tab 키에 의한 포커스 이동에서 제외되어야 합니다.",
        "양수로 설정된 컴포넌트 중 작은 숫자의 컴포넌트부터 포커스를 받아야 합니다.",
        "양수로 설정된 컴포넌트를 모두 순회한 후 0 또는 미설정 컴포넌트로 포커스가 이동되어야 합니다.",
        "동일한 양수 값을 설정한 경우 소스에 정의된 순서대로 포커스가 이동되어야 합니다.",
        "0 또는 미설정 컴포넌트는 소스에 정의된 순서대로 포커스가 이동되어야 합니다.",
        "컴포넌트가 포커스를 받을 수 없는 상태(disabled 등)이면 tabIndex 속성값에 관계없이 포커스가 이동하지 않아야 합니다.",
        "nextTabID 속성 설정 시 tabIndex 속성에 의한 순서는 무시되고 nextTabID 에 설정된 컴포넌트로 포커스가 이동되어야 합니다.",
        "accessibility=true 이면 내부 'ul' 요소(role='listbox')에 tabindex 가 적용되어야 합니다.",
        "accessibility=false 이면 루트 'div' 요소에 tabindex 가 적용되어야 합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
	let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};




scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 input2 있으면 삭제
    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    // 기존 button2 있으면 삭제
    if (typeof button2 !== 'undefined') {
        button2.remove();
    }

    // 기존 selectbox2 있으면 삭제
    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }

    // gdl_multiselect 재생성
    $c.gcm.createDataListMultiSelect();

    // 조건 설정 (target)
    let properties = {
        tabIndex: scwin.gVar["cTabIndexTarget"],
    };

    let cList = $c.gcm.createCList(properties);

    // 조건 설정 (input)
    let properties_input = {
        tabIndex: scwin.gVar["cTabIndexInput"],
    };

    let cList_input = $c.gcm.createCList(properties_input);

    // 조건 설정 (button)
    let properties_button = {
        tabIndex: scwin.gVar["cTabIndexButton"],
    };

    let cList_button = $c.gcm.createCList(properties_button);

    // 조건 설정 (selectbox)
    let properties_selectbox = {
        tabIndex: scwin.gVar["cTabIndexSelectBox"],
    };

    let cList_selectbox = $c.gcm.createCList(properties_selectbox);

    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();
    let strStartComp = '';

    strStartComp += '<xf:input ' + strNameSpace + ' tabIndex="1" initValue="start" style="width:144px; height:21px;"></xf:input>';

    scwin.startcomp = await $p.dynamicCreate(
        "startcomp",
        "input",
        strStartComp,
        grp_comp
    );

    $c.gcm.createBasicInput(cList_input, 'ev:onfocus="scwin.input2_onfocus"', "input2");
    $c.gcm.createBasicButton(cList_button, 'ev:onfocus="scwin.button2_onfocus"', "button2");
    $c.gcm.createBasicSelectBox(cList_selectbox, 'ev:onfocus="scwin.selectbox2_onfocus"', "selectbox2");
    $c.gcm.createBasicMultiSelect(cList, 'ev:onfocus="scwin.target1_onfocus"');

    input2.setValue("input");
    scwin.changeDisplay();
}



scwin.changeDisplay = function() {
    // multiselect 부모 컨테이너가 flex/inline-block 흐름이라 block 자식이어도 같은 줄에 표시됨
    // width:100% + flex-basis:100% 로 줄 전체 차지하여 강제 줄바꿈 효과
    setTimeout(function() {
        var rootEl = document.getElementById('mf_target1') || document.getElementById('target1');
        if (rootEl) {
            rootEl.style.setProperty('display', 'block', 'important');            
            rootEl.style.setProperty('flex-basis', '100%', 'important');
        }
    }, 100);
}
